insert into test_design_template (
    id, project_id, name, description, prompt_key, prompt_version, coverage_types,
    case_count_per_requirement, context_defaults_json, enabled, created_by, updated_by,
    created_at, updated_at
) values (
    cast(#{id} as uuid), #{projectId}, #{name}, #{description}, #{promptKey}, #{promptVersion},
    #{coverageTypes}, #{caseCountPerRequirement},
    coalesce(cast(#{contextDefaultsJson} as jsonb), '{}'::jsonb),
    #{enabled}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)

mapper.select:
select count(*)
from test_design_task
where status = #{status}

select count(*)
from test_design_candidate
where status = #{status}

select 
from test_design_task
where project_id = #{projectId}
  and idempotency_key = #{idempotencyKey}
limit 1

mapper.update:
update test_design_task
set status = #{nextStatus},
    error_message = null,
    updated_at = #{updatedAt}
where id = cast(#{id} as uuid)
  and status = #{expectedStatus}

with stale_tasks as (
    select id
    from test_design_task
    where status = 'RUNNING'
      and updated_at < #{staleBefore}
    order by updated_at asc
    limit #{limit}
)
update test_design_task
set status = 'FAILED',
    error_message = #{errorMessage},
    updated_at = #{failedAt}
where id in (select id from stale_tasks)
  and status = 'RUNNING'
  and updated_at < #{staleBefore}

with stale_candidates as (
    select id
    from test_design_candidate
    where status = 'PUBLISHING'
      and updated_at < #{staleBefore}
    order by updated_at asc
    limit #{limit}
)
update test_design_candidate
set status = 'FAILED',
    error_message = #{errorMessage},
    version = version + 1,
    updated_at = #{failedAt}
where id in (select id from stale_candidates)
  and status = 'PUBLISHING'
  and updated_at < #{staleBefore}

